27	import org.slf4j.Logger;
28	import org.slf4j.LoggerFactory;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.rest.advice.DailyOwnerRegistrationLimitException;
47	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
48	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
49	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
50	import org.springframework.samples.petclinic.rest.advice.OwnerCityAtCapacityException;
51	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
52	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    private final TelephoneNormalizer telephoneNormalizer;
81	
82	    private final AddressNormalizer addressNormalizer;
83	
84	    public OwnerRestControllerV1(ClinicService clinicService,
85	                                 OwnerMapper ownerMapper,
86	                                 PetMapper petMapper,
87	                                 VisitMapper visitMapper,
88	                                 TelephoneNormalizer telephoneNormalizer,
89	                                 AddressNormalizer addressNormalizer) {
90	        this.clinicService = clinicService;
91	        this.ownerMapper = ownerMapper;
92	        this.petMapper = petMapper;
93	        this.visitMapper = visitMapper;
94	        this.telephoneNormalizer = telephoneNormalizer;
95	        this.addressNormalizer = addressNormalizer;
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
101	        Collection<Owner> owners;
102	        if (lastName != null) {
103	            owners = this.clinicService.findOwnerByLastName(lastName);
104	        } else {
105	            owners = this.clinicService.findAllOwners();
106	        }
107	        if (owners.isEmpty()) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
116	        Owner owner = this.clinicService.findOwnerById(ownerId);
117	        if (owner == null) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
126	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
127	        rejectBlankOwnerFields(ownerFieldsDto);
128	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
129	        if (!sharesHousehold) {
130	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
131	        }
132	        rejectCityAtCapacity(ownerFieldsDto.getCity());
133	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
134	        rejectDailyRegistrationLimit(registrationDate);
135	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
136	        rejectDuplicateTelephone(normalizedTelephone);
137	        ownerFieldsDto.setTelephone(normalizedTelephone);
138	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
139	        HttpHeaders headers = new HttpHeaders();
140	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
141	        owner.setRegistrationDate(registrationDate);
142	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
143	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
144	        if (sharesHousehold) {
145	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
146	        }
147	        this.clinicService.saveOwner(owner);
148	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
149	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
159	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
160	        if (currentOwner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        currentOwner.setAddress(ownerFieldsDto.getAddress());
164	        currentOwner.setCity(ownerFieldsDto.getCity());
165	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
166	        currentOwner.setLastName(ownerFieldsDto.getLastName());
167	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
168	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
169	        this.clinicService.saveOwner(currentOwner);
170	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Transactional
175	    @Override
176	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
177	        Owner owner = this.clinicService.findOwnerById(ownerId);
178	        if (owner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        this.clinicService.deleteOwner(owner);
182	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
188	        Owner owner = this.clinicService.findOwnerById(ownerId);
189	        if (owner == null) {
190	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	        }
192	        HttpHeaders headers = new HttpHeaders();
193	        Pet pet = petMapper.toPet(petFieldsDto);
194	        owner.setId(ownerId);
195	        pet.setOwner(owner);
196	        pet.getType().setName(null);
197	        this.clinicService.savePet(pet);
198	        PetDto petDto = petMapper.toPetDto(pet);
199	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
200	            .buildAndExpand(pet.getId()).toUri());
201	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
207	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
208	        if (currentOwner != null) {
209	            Pet currentPet = this.clinicService.findPetById(petId);
210	            if (currentPet != null) {
211	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
212	                currentPet.setName(petFieldsDto.getName());
213	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
214	                this.clinicService.savePet(currentPet);
215	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
216	            }
217	        }
218	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
224	        HttpHeaders headers = new HttpHeaders();
225	        Visit visit = visitMapper.toVisit(visitFieldsDto);
226	        Pet pet = new Pet();
227	        pet.setId(petId);
228	        visit.setPet(pet);
229	        this.clinicService.saveVisit(visit);
230	        VisitDto visitDto = visitMapper.toVisitDto(visit);
231	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
232	            .buildAndExpand(visit.getId()).toUri());
233	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
234	    }
235	
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
240	        Owner owner = this.clinicService.findOwnerById(ownerId);
241	        if (owner != null) {
242	            Pet pet = owner.getPet(petId);
243	            if (pet != null) {
244	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
245	            }
246	        }
247	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	    }
249	
250	    /**
251	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
252	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
253	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
254	     * blank (e.g. {@code "   "}). The offending field names are reported through an
255	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
256	     * as a 400 response carrying an {@code errors} array of field names.
257	     *
258	     * @param ownerFieldsDto the submitted owner fields
259	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
260	     */
261	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
262	        List<String> blankFields = new ArrayList<>();
263	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
264	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
265	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
266	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
267	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
268	        if (!blankFields.isEmpty()) {
269	            throw new InvalidOwnerFieldsException(blankFields);
270	        }
271	    }
272	
273	    private void addIfBlank(List<String> blankFields, String field, String value) {
274	        if (value != null && value.isBlank()) {
275	            blankFields.add(field);
276	        }
277	    }
278	
279	    /**
280	     * Normalizes an owner's optional email address. When present it is stored and returned
281	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
282	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
283	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
284	     * method runs.
285	     *
286	     * @param email the raw email value from the request, or {@code null} when omitted
287	     * @return the lower-cased email, or {@code null} when none was supplied
288	     */
289	    private String normalizeEmail(String email) {
290	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
291	    }
292	
293	    /**
294	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
295	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
296	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
297	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
298	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
299	     *
300	     * @param city the city of the owner being created
301	     * @param lastName the last name of the owner being created
302	     * @return the formatted customer code
303	     */
304	    private String nextCustomerCode(String city, String lastName) {
305	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
306	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
307	        long sequence = this.clinicService.findAllOwners().stream()
308	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
309	            .count() + 1L;
310	        return String.format("%s-%s-%04d", city3, last3, sequence);
311	    }
312	
313	    /**
314	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
315	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
316	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
317	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
318	     * new owner and surfaced as the read-only {@code namesakeCount} field.
319	     *
320	     * @param firstName the first name of the owner being created
321	     * @param lastName the last name of the owner being created
322	     * @return the number of existing owners with the same first and last name (case-insensitive)
323	     */
324	    private int namesakeCount(String firstName, String lastName) {
325	        return (int) this.clinicService.findAllOwners().stream()
326	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
327	                && equalsIgnoreCase(owner.getLastName(), lastName))
328	            .count();
329	    }
330	
331	    private boolean equalsIgnoreCase(String a, String b) {
332	        return a == null ? b == null : a.equalsIgnoreCase(b);
333	    }
334	
335	    /**
336	     * The maximum number of owners a single city may contain. Once a city already holds this many
337	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
338	     */
339	    private static final long MAX_OWNERS_PER_CITY = 50L;
340	
341	    /**
342	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
343	     * owners. Existing owners are matched to the requested city case-insensitively (using
344	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
345	     * the per-city counting used for the customer code. A city at capacity is reported through an
346	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
347	     * 409 Conflict response.
348	     *
349	     * @param city the city of the owner being created
350	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
351	     */
352	    private void rejectCityAtCapacity(String city) {
353	        long owners = this.clinicService.findAllOwners().stream()
354	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
355	            .count();
356	        if (owners >= MAX_OWNERS_PER_CITY) {
357	            throw new OwnerCityAtCapacityException(city);
358	        }
359	    }
360	
361	    /**
362	     * The maximum number of owners that may be registered on a single day. Once this many owners
363	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
364	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
365	     */
366	    private static final long MAX_OWNERS_PER_DAY = 100L;
367	
368	    /**
369	     * Resolves the effective registration date for a create request: the value supplied in the
370	     * request when present, otherwise the server's current date. The result is the raw effective
371	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
372	     *
373	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
374	     * @return the supplied date, or today when none was supplied
375	     */
376	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
377	        return suppliedDate != null ? suppliedDate : LocalDate.now();
378	    }
379	
380	    /**
381	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
382	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
383	     * the effective registration date so that a weekend value - whether supplied in the request or
384	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
385	     * registration date (such as the membership number's year segment and the daily create-limit
386	     * bucket) uses the adjusted business day.
387	     *
388	     * @param date the effective registration date
389	     * @return the same date when it is a weekday, otherwise the next Monday
390	     */
391	    private LocalDate businessDay(LocalDate date) {
392	        DayOfWeek dayOfWeek = date.getDayOfWeek();
393	        if (dayOfWeek == DayOfWeek.SATURDAY) {
394	            return date.plusDays(2);
395	        }
396	        if (dayOfWeek == DayOfWeek.SUNDAY) {
397	            return date.plusDays(1);
398	        }
399	        return date;
400	    }
401	
402	    /**
403	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
404	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
405	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
406	     * renders as a 429 Too Many Requests response.
407	     *
408	     * @param date the registration date of the owner being created (today)
409	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
410	     */
411	    private void rejectDailyRegistrationLimit(LocalDate date) {
412	        long owners = this.clinicService.findAllOwners().stream()
413	            .filter(owner -> date.equals(owner.getRegistrationDate()))
414	            .count();
415	        if (owners >= MAX_OWNERS_PER_DAY) {
416	            throw new DailyOwnerRegistrationLimitException(date);
417	        }
418	    }
419	
420	    /**
421	     * Rejects a create request whose normalized telephone is already used by any existing owner.
422	     * Existing owners' telephones are reduced to the same canonical form (via
423	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
424	     * only in formatting still collide. A collision is reported through a
425	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
426	     * as a 409 Conflict response.
427	     *
428	     * @param normalizedTelephone the canonical telephone of the owner being created
429	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
430	     */
431	    private void rejectDuplicateTelephone(String normalizedTelephone) {
432	        boolean duplicate = existingOwnerMatches(
433	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
434	            normalizedTelephone);
435	        if (duplicate) {
436	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
437	        }
438	    }
439	
440	    /**
441	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
442	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
443	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
444	     * and the owner being created to the same canonical key and reject a match.
445	     *
446	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
447	     * @param key the canonical key of the owner being created
448	     * @return {@code true} if some existing owner shares the key
449	     */
450	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
451	        return this.clinicService.findAllOwners().stream()
452	            .map(keyExtractor)
453	            .filter(Objects::nonNull)
454	            .anyMatch(key::equals);
455	    }
456	
457	    /**
458	     * Rejects a create request that shares a household with an existing owner: another owner already
459	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
460	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
461	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
462	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
463	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
464	     * check when the request opts in via {@code sharesHousehold}.
465	     *
466	     * @param lastName the last name of the owner being created
467	     * @param address the address of the owner being created
468	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
469	     */
470	    private void rejectDuplicateHousehold(String lastName, String address) {
471	        String canonicalLastName = canonicalizeHousehold(lastName);
472	        String canonicalAddress = canonicalizeHousehold(address);
473	        if (canonicalLastName == null || canonicalAddress == null) {
474	            return;
475	        }
476	        boolean duplicate = this.clinicService.findAllOwners().stream()
477	            .anyMatch(owner -> canonicalLastName.equals(canonicalizeHousehold(owner.getLastName()))
478	                && canonicalAddress.equals(canonicalizeHousehold(owner.getAddress())));
479	        if (duplicate) {
480	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
481	        }
482	    }
483	
484	    /**
485	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
486	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
487	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
488	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
489	     *
490	     * @param value the raw field value, or {@code null}
491	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
492	     */
493	    private String canonicalizeHousehold(String value) {
494	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
495	    }
496	
497	    /**
498	     * Derives the stable, shared {@code householdId} for an owner joining a household via
499	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
500	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
501	     * owner with the same last name at the same address - regardless of casing or spacing - is
502	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
503	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
504	     *
505	     * @param lastName the last name of the owner being created
506	     * @param address the address of the owner being created
507	     * @return the shared household identifier
508	     */
509	    private String householdId(String lastName, String address) {
510	        String key = canonicalizeHousehold(lastName) + "\n" + canonicalizeHousehold(address);
511	        try {
512	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
513	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
514	            StringBuilder sb = new StringBuilder(digest.length * 2);
515	            for (byte b : digest) {
516	                sb.append(String.format("%02X", b));
517	            }
518	            return sb.substring(0, 16);
519	        } catch (java.security.NoSuchAlgorithmException e) {
520	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
521	        }
522	    }
523	}
